}

/* ===== EVENT 3 - the drawing viewer ===================================== */
.cabin-calculator-ssr .drawing-viewer { margin: 10px 0 4px; }
.cabin-calculator-ssr .drawing-tabs { display: flex; flex-wrap: wrap; gap: 6px; margin: 0 0 8px; padding: 0; border: 0; }
